def a_fahrenheit(celsius):
    """Convierte grados Celsius a Fahrenheit."""
    return celsius * 9 / 5 + 32


def promedio(datos):
    """Devuelve la media aritmética de una lista no vacía."""
    return sum(datos) / len(datos)


media = promedio([18.5, 21.0, 19.4])
print(f"Media: {media:.1f} °C")
print(f"Equivalente: {a_fahrenheit(media):.1f} °F")

def descuento_para(monto):
    """Devuelve el porcentaje de descuento según el monto."""
    if monto >= 300:
        return 10
    if monto >= 100:
        return 5
    return 0


def total_final(monto):
    """Aplica el descuento correspondiente y devuelve el total."""
    porcentaje = descuento_para(monto)
    return monto * (1 - porcentaje / 100)


for monto in (80, 150, 420):
    print(f"{monto}: {total_final(monto):.2f}")
